using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task Initialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _chatClient;
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Assert - basic response validation
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
        var content = response.Messages[^1].Text;
        Assert.IsFalse(string.IsNullOrWhiteSpace(content));
    }

    [TestMethod]
    public async Task Chat_ResponseQuality_Coherence()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var content = response.Messages[^1].Text ?? string.Empty;

        // Evaluate coherence using the quality evaluator
        var coherenceEvaluator = new CoherenceEvaluator();
        var result = await coherenceEvaluator.EvaluateAsync(
            messages,
            response,
            _evaluatorClient);

        // Assert
        Assert.IsNotNull(result);
        foreach (var metric in result)
        {
            if (metric.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 3,
                    $"Coherence score {numericValue.Value} is below threshold 3");
            }
        }
    }

    [TestMethod]
    public async Task Chat_ResponseQuality_Relevance()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the benefits of exercise?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Evaluate relevance
        var relevanceEvaluator = new RelevanceEvaluator();
        var result = await relevanceEvaluator.EvaluateAsync(
            messages,
            response,
            _evaluatorClient);

        // Assert
        Assert.IsNotNull(result);
        foreach (var metric in result)
        {
            if (metric.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= 3,
                    $"Relevance score {numericValue.Value} is below threshold 3");
            }
        }
    }
}

